[]
{}
Array.new
Hash.new
Hash.new { |h, k| h[k] = [] }
Hash.new { |h, k| h[k] = {} }
Hash.new { 0 }
Hash.new { Array.new }
Hash.new { Hash.new }
Hash.new { {} }
Hash.new { [] }
Hash.new(0)
Hash.new(false)
Hash.new(true)
Hash.new(nil)
Hash.new(BigDecimal(0))
Hash.new(BigDecimal(0.0))
Hash.new(0.0)
Hash.new(0.0.to_d)

# okay -- beware this will discard mutations and only remember assignments
Hash.new { Array.new }
Hash.new { Hash.new }
Hash.new { {} }
Hash.new { [] }

# good - using a proc will create a new object for each key
h = Hash.new
h.default_proc = ->(h, k) { [] }
h.default_proc = ->(h, k) { {} }

# good - using a block will create a new object for each key
Hash.new { |h, k| h[k] = [] }
Hash.new { |h, k| h[k] = {} }
